import json
a = json.load(open('/tmp/metrics_cached.json')); b = json.load(open('metrics.json'))
diffs=[]
for ka, kb in zip(a['models'], b['models']):
    for k in ka:
        if k in ('runtime_seconds',): continue
        if ka[k] != kb[k]: diffs.append((ka['name'], k, ka[k], kb[k]))
for k in a:
    if k in ('models','total_runtime_seconds'): continue
    if a[k] != b[k]: diffs.append(('top', k, a[k], b[k]))
print("non-runtime differences between the cached run and the clean run:", diffs or "NONE")
print("total runtime: cached", a['total_runtime_seconds'], "clean", b['total_runtime_seconds'])
